            diag = [(start_r, start_c)]
            for dr in range(1, 6):
                nr, nc = start_r + dr, start_c + dr
                if 0 <= nr < 15 and 0 <= nc < 6 and grid[nr][nc] == 9:
                    diag.append((nr, nc))
                else:
                    break
            if len(diag) >= 2:
                diag_starts.append(diag)

    if not diag_starts:
        return result

    # Find diagonal with most bilateral matches  
    best_diag = None
    max_bilateral = -1

    for diag in diag_starts:
        bilateral_count = 0
        for r, left_col in diag:
            if 0 <= 6 + left_col < 15 and grid[r][6 + left_col] == 9:
                bilateral_count += 1
        if bilateral_count > max_bilateral:
            max_bilateral = bilateral_count
            best_diag = diag

    if best_diag and max_bilateral >= 2:
        for r, left_col in best_diag:
            result[r][5:8] = [0, 0, 0]
    else:
        sorted_diags = sorted(diag_starts, key=lambda x: x[0][0])
